def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[]
    for r in range(0,h,3):
        row=[]
        for c in range(0,w,3):
            colors={v for line in grid[r:r+3] for v in line[c:c+3] if v not in (0,5)}
            row.append(next(iter(colors)) if colors else 0)
        out.append(row)
    return out
